import os
from google.cloud import storage

def get_storage_client():
    project_id = os.environ.get("GCP_PROJECT_ID")
    if not project_id:
        raise ValueError("GCP_PROJECT_ID environment variable not set.")
    return storage.Client(project=project_id)

from storage_client import get_storage_client
from storage_models import ListPrefixResponse

def list_objects_with_prefix(payload, config=None):
    config = config or {}
    client = get_storage_client()
    bucket_name = config.get("bucket")
    if not bucket_name:
        raise ValueError("Bucket name not provided in config.")

    bucket = client.bucket(bucket_name)
    prefix = payload.get("prefix", "")

    objects = []
    for blob in client.list_blobs(bucket_name, prefix=prefix):
        objects.append({
            "object_name": blob.name,
            "size": blob.size,
            "content_type": blob.content_type,
            "updated": blob.updated.isoformat()
        })

    return ListPrefixResponse(objects=objects).__dict__

from google.cloud import vision
from storage_client import get_storage_client

def run_ocr_on_stored_document(payload, config=None):
    config = config or {}
    client = vision.ImageAnnotatorClient()
    bucket_name = config.get("bucket")
    object_name = payload.get("object_name")

    if not bucket_name or not object_name:
        raise ValueError("Bucket name and object name must be provided.")

    image = vision.Image({"source": {"image_uri": f"gs://{bucket_name}/{object_name}"}})
    response = client.document_text_detection(image=image)

    full_text = response.full_text_annotation.text
    return {"text": full_text}

from google.cloud import translate_v2 as translate

def translate_stored_text(payload, config=None):
    config = config or {}
    client = translate.Client()

    text_to_translate = payload.get("text")
    target_language = payload.get("target_language", "en")

    if not text_to_translate:
        raise ValueError("Text to translate must be provided.")

    result = client.translate(text_to_translate, target_language=target_language)

    return {"translated_text": result["translatedText"], "source_language": result["detectedSourceLanguage"]}

import os
import vertexai
from vertexai.language_models import TextEmbeddingModel

def embed_asset_metadata(payload, config=None):
    config = config or {}
    project_id = os.environ.get("GCP_PROJECT_ID")
    location = os.environ.get("GCP_REGION", "us-central1")

    if not project_id:
        raise ValueError("GCP_PROJECT_ID environment variable not set.")

    vertexai.init(project=project_id, location=location)
    model = TextEmbeddingModel.from_pretrained("textembedding-gecko@001")

    text_to_embed = payload.get("text")
    if not text_to_embed:
        raise ValueError("Text to embed must be provided.")

    embeddings = model.get_embeddings([text_to_embed])

    return {"embedding": embeddings[0].values}
